export const getBookCharacterSuggestionsControllerListUrl = (
  bookId: string,
  params?: BookCharacterSuggestionsControllerListParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/books/${bookId}/character-suggestions?${stringifiedParams}`
    : `/api/books/${bookId}/character-suggestions`;
};

